/**
 * The canonical-schema pin — the first cross-runtime byte agreement on
 * the schema plane itself.
 *
 * `library/cas/schemas/*.json` are generated by executing the Lean
 * self-codec (`lake exe schemas`): each file's bytes ARE the
 * schema-node payload (`{"revision":0,"value":<ast>}` under the
 * canonical compact rendering) of one registered code. This suite
 * mirrors every registered code through the TypeScript constructors
 * and asserts `CanonicalSchema.payloadOf` answers the same bytes —
 * closing the pin the implementation plan held open ("asserting the
 * schema bytes agree across runtimes is BLOCKED on the schema
 * commission's Lean Ast codec").
 *
 * Per the ratified harness rulings: the TS codes hand-mirror the Lean
 * registry (the drift tripwire), nothing here writes or repairs a
 * fixture, and a missing fixture is a red suite.
 */
import { expect, it } from "@effect/vitest"
import { readFileSync } from "node:fs"
import { Effect, Option } from "effect"
import { Cas } from "../src/index.ts"

const { CanonicalSchema, ConformanceVector } = Cas

const schemasDir = new URL("../../cas/schemas/", import.meta.url)

const fixtureBytes = (name: string): Uint8Array =>
  new Uint8Array(readFileSync(new URL(`${name}.json`, schemasDir)))

/** Lean `SchemasMain.PinSample`, hand-mirrored: every constructor the
 * deriving handler reaches. */
const pinSample = CanonicalSchema.struct({
  count: CanonicalSchema.field(CanonicalSchema.integerAst),
  flag: CanonicalSchema.field(CanonicalSchema.booleanAst),
  items: CanonicalSchema.field(CanonicalSchema.array(CanonicalSchema.stringAst)),
  label: CanonicalSchema.field(CanonicalSchema.stringAst),
  note: CanonicalSchema.optionalField(CanonicalSchema.stringAst),
  root: CanonicalSchema.field(CanonicalSchema.ref(9)),
  unit: CanonicalSchema.field(CanonicalSchema.nullAst),
})

/** Lean `SchemasMain.literalPin`, hand-mirrored: the `Literal`
 * spellings the deriving handler does not reach. */
const literalPin = CanonicalSchema.struct({
  a: CanonicalSchema.field(CanonicalSchema.literal(null)),
  b: CanonicalSchema.field(CanonicalSchema.literal(true)),
  c: CanonicalSchema.optionalField(CanonicalSchema.literal(-7)),
  d: CanonicalSchema.field(CanonicalSchema.literal("pinned")),
})

/** The registry, name-for-name with `library/cas/tools/Schemas.lean`. */
const registry: ReadonlyArray<readonly [string, Cas.CanonicalSchema.Ast]> = [
  ["vector-document", ConformanceVector.vectorAst],
  ["vector-index", ConformanceVector.indexAst],
  ["pin-sample", pinSample],
  ["literal-pin", literalPin],
] as const

it.effect("every registered code's payload bytes agree across runtimes", () =>
  Effect.sync(() => {
    for (const [name, ast] of registry) {
      const expected = fixtureBytes(name)
      const actual = CanonicalSchema.payloadOf(ast)
      expect(`${name} ${Buffer.from(actual).toString("utf8")}`)
        .toBe(`${name} ${Buffer.from(expected).toString("utf8")}`)
    }
  }))

it.effect("every registered code survives the annotation round trip", () =>
  Effect.sync(() => {
    for (const [name, ast] of registry) {
      const carried = CanonicalSchema.astOf(CanonicalSchema.fromAst(ast))
      expect(Option.isSome(carried)).toBe(true)
      if (Option.isSome(carried)) {
        expect(`${name} ${Buffer.from(CanonicalSchema.payloadOf(carried.value)).toString("utf8")}`)
          .toBe(`${name} ${Buffer.from(CanonicalSchema.payloadOf(ast)).toString("utf8")}`)
      }
    }
  }))
